import cn from 'classnames';
import { EmbedVideoProps } from './embed-video.type';
import './embed-video.scss';

export function EmbedVideo({
  id,
  className,
  videoImageFallback,
  source,
  playsInline = true,
  loop = true,
  muted = true,
  autoPlay = true,
  height,
  width,
  poster,
  controls = true,
}: EmbedVideoProps) {
  return (
    <div className={cn('embed', className)}>
      <div id={id} className="cmp-embed">
        <div>
          <video
            {...(autoPlay && { autoPlay: true })}
            {...(controls && { controls: true })}
            {...(loop && { loop: true })}
            {...(muted && { muted: true })}
            {...(playsInline && { playsInline: true })}
            width={width}
            height={height}
            poster={poster}
          >
            {source && source.length ? (
              <>
                {source.map((item) => (
                  <source key={item.id} src={item.url} type={item.type} />
                ))}
              </>
            ) : (
              <picture>
                <img
                  id={id}
                  src={videoImageFallback}
                  className="lazyload cq-dd-videoThumbnail"
                  data-sizes="auto"
                  data-height="auto"
                />
              </picture>
            )}
          </video>
        </div>
      </div>
    </div>
  );
}

export default EmbedVideo;
